CREATE TEMP TABLE rpmd_indicator_drafts (code text, name text, category_code text, owner_code text, definition text, unit_code text, data_type text, direction text, source_reference text, dimension_schema jsonb) ON COMMIT DROP;
;

SELECT d.code, d.name, c.id, o.id, true
FROM rpmd_indicator_drafts d
JOIN sababuka.categories c ON c.code = d.category_code
LEFT JOIN sababuka.organizations o ON o.code = d.owner_code
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, category_id = EXCLUDED.category_id, owner_organization_id = EXCLUDED.owner_organization_id, is_active = true, archived_at = NULL;

SELECT i.id, 1, d.definition, NULL, u.id, 'annual', d.data_type, d.dimension_schema, d.direction, d.source_reference, 'internal', DATE '2025-01-01', 'draft',
       'Draf hasil inventarisasi RPJMD. Menunggu review strategis Bapperida dan verifikasi teknis OPD.'
FROM rpmd_indicator_drafts d
JOIN sababuka.indicators i ON i.code = d.code
JOIN sababuka.units u ON u.code = d.unit_code
ON CONFLICT (indicator_id, version_number) DO UPDATE SET definition = EXCLUDED.definition, formula = EXCLUDED.formula, unit_id = EXCLUDED.unit_id, frequency = EXCLUDED.frequency, data_type = EXCLUDED.data_type, dimension_schema = EXCLUDED.dimension_schema, direction = EXCLUDED.direction, source_reference = EXCLUDED.source_reference, access_level = EXCLUDED.access_level, effective_from = EXCLUDED.effective_from, status = 'draft', change_notes = EXCLUDED.change_notes, submitted_by = NULL, submitted_at = NULL, approved_by = NULL, approved_at = NULL, updated_at = now();

DELETE FROM sababuka.indicator_organizations io USING sababuka.indicator_versions iv, sababuka.indicators i, rpmd_indicator_drafts d WHERE io.indicator_version_id = iv.id AND iv.indicator_id = i.id AND i.code = d.code;
SELECT iv.id, o.id, 'primary_producer', true
FROM rpmd_indicator_drafts d
JOIN sababuka.indicators i ON i.code = d.code
JOIN sababuka.indicator_versions iv ON iv.indicator_id = i.id AND iv.version_number = 1
JOIN sababuka.organizations o ON o.code = d.owner_code
ON CONFLICT DO NOTHING;

CREATE TEMP TABLE rpmd_target_drafts (indicator_code text, period_code text, numeric_value numeric, text_value text) ON COMMIT DROP;
;
SELECT iv.id, p.id, t.numeric_value, t.text_value, 'Target draf RPJMD; menunggu pengesahan Bapperida.'
FROM rpmd_target_drafts t
JOIN sababuka.indicators i ON i.code = t.indicator_code
JOIN sababuka.indicator_versions iv ON iv.indicator_id = i.id AND iv.version_number = 1
JOIN sababuka.periods p ON p.code = t.period_code
ON CONFLICT (indicator_version_id, period_id, geography_id, dimension_hash) DO UPDATE SET numeric_value = EXCLUDED.numeric_value, text_value = EXCLUDED.text_value, notes = EXCLUDED.notes, updated_at = now();

UPDATE sababuka.categories SET is_active = false, archived_at = COALESCE(archived_at, now()) WHERE code IN ('PANGAN_AGRO','INVESTASI_INDUSTRI','DESA_EKONOMI','SDM_SEJAHTERA','KONEKTIVITAS_LAYANAN');
UPDATE sababuka.policy_focuses SET is_active = false, archived_at = COALESCE(archived_at, now()) WHERE code = 'PILOT_ANTARA';


COMMIT;
